"""Tiny dungeon crawler: chained room nodes with a treasure vault.

A Hunter walker inspects rooms in chain order, counting how many it has
seen, and disengages the moment it enters the vault so no room past the
treasure is ever visited.
"""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_seen += 1;
        print(f"Inspecting room #{self.rooms_seen}: {here.name}");
        if here.is_treasure {
            print(f"Treasure found in '{here.name}'! Search ends after {self.rooms_seen} rooms.");
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Dragon's Lair");

    root spawn Hunter();
}
