export function RouteListener({ onChange }: { onChange?: () => void } = {}) {
  const location = useLocation();
  useLayoutEffect(() => {
    if (onChange) onChange();
  }, [location, onChange]);
  return <></>;
}

interface LazyRouteProps {
  auth?: string | string[];
  lazy: React.LazyExoticComponent<() => JSX.Element>;
}

export function LazyRoute(props: LazyRouteProps) {
  const { auth, lazy: LazyComponent } = props;

  return (
    <Suspense
      fallback={
        <div
          style={{
            width: '100%',
            height: '100%',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
          }}>
          <Spin spinning />
        </div>
      }>
      <Authorized auth={auth} fallback={<Page403 />}>
        <LazyComponent />
      </Authorized>
    </Suspense>
  );
}

