"""Order audit walk: skip invalid orders and halt the whole walk on fraud."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Order auditor starting");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged on order amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order amount={here.amount}");
                visit [-->] else { disengage; }
            } else {
                print(f"[AUDIT] approved order amount={here.amount}");
                visit [-->] else { disengage; }
            }
        }
    }
}

with entry {
    root ++> Order(amount=100, valid=True, fraud=False)
        ++> Order(amount=50, valid=False, fraud=False)
        ++> Order(amount=200, valid=True, fraud=False)
        ++> Order(amount=999, valid=True, fraud=True)
        ++> Order(amount=300, valid=True, fraud=False);
    root spawn OrderAuditor();
}
