"""Weather sweep: stations report temperature as a walker visits them, then summarize."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_temp: float = 0.0;
    has max_temp: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        print(f"[{here.name} @ {here.location}] {here.celsius} C");
        self.readings.append(here.celsius);
        if len(self.readings) == 1 {
            self.min_temp = here.celsius;
            self.max_temp = here.celsius;
        } else {
            new_min = self.min_temp if self.min_temp < here.celsius else here.celsius;
            new_max = self.max_temp if self.max_temp > here.celsius else here.celsius;
            self.min_temp = new_min;
            self.max_temp = new_max;
        }
        visit [-->];
    }
}

with entry {
    s1 = Station(name="North", location="Ridge", celsius=18.5);
    s2 = Station(name="East", location="Valley", celsius=22.0);
    s3 = Station(name="South", location="Coast", celsius=15.7);
    s4 = Station(name="West", location="Plateau", celsius=27.3);

    root ++> s1 ++> s2 ++> s3 ++> s4;

    sweep = WeatherSweep();
    root spawn sweep;

    print("All readings: " + str(sweep.readings));
    print(f"min = {sweep.min_temp} C, max = {sweep.max_temp} C");
}
