"""Depot network monitor: traverse from all depots in one spawn, flag low-stock stores."""

node Store {
    has name: str = "";
    has stock: int = 0;
    has low_stock: bool = False;

    def flag_if_low() -> None {
        self.low_stock = self.stock < 20;
    }
}

node Depot {
    has code: str = "";
}

edge Supplies { has route: str = ""; }

walker StockAuditor {
    has flagged: list[str] = [];

    can start with Root entry {
        print("Anchoring combined query from all depots...");
        visit [-->];
    }

    can audit_depot with Depot entry {
        print(f"Scanning depot {here.code}");
        visit [-->];
    }

    can audit_store with Store entry {
        here.flag_if_low();
        if here.low_stock {
            label = f"{here.name} (stock={here.stock})";
            self.flagged.append(label);
            print(f"[LOW] {label}");
        } else {
            print(f"[OK]  {here.name} (stock={here.stock})");
        }
    }
}

with entry {
    d_north = Depot(code="D-NORTH");
    d_east = Depot(code="D-EAST");
    d_west = Depot(code="D-WEST");

    s_a = Store(name="Store A", stock=55);
    s_b = Store(name="Store B", stock=12);
    s_c = Store(name="Store C", stock=30);
    s_d = Store(name="Store D", stock=8);
    s_e = Store(name="Store E", stock=100);

    root ++> d_north;
    root ++> d_east;
    root ++> d_west;

    d_north +>:Supplies(route="truck-1"):+> s_a;
    d_north +>:Supplies(route="truck-1"):+> s_b;
    d_east +>:Supplies(route="truck-2"):+> s_c;
    d_east +>:Supplies(route="truck-2"):+> s_d;
    d_west +>:Supplies(route="truck-3"):+> s_e;

    auditor = StockAuditor();
    root spawn auditor;
    print(f"Flagged {len(auditor.flagged)} low-stock stores: {auditor.flagged}");
}
