"""Quiz app grader: walk quiz nodes, collect strictly typed integer scores, and print the class average."""

node Quiz {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has score: int = 0;
}

walker Grader {
    has reports: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        report here.score;
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Quiz(title="Alice", score=92)
        ++> Quiz(title="Bob", score=85)
        ++> Quiz(title="Carol", score=88)
        ++> Quiz(title="Dave", score=76)
        ++> Quiz(title="Eve", score=95);

    grader = root spawn Grader();
    collected = grader.reports;
    total = 0;
    for s in collected {
        total += s;
    }
    count = len(collected);
    class_average = 0.0;
    if count > 0 {
        class_average = total / count;
    }
    print(f"Collected scores: {collected}");
    print(f"Class average: {class_average}");
}
