"""Restaurant kitchen line health-inspection demo.

A patrol walker visits each station on the line (grill, fryer, cold prep).
Two checks run at every station:
  1. Temperature check: anything above 40 C is flagged as a violation.
  2. Visit log: every station visit is logged on the walker itself.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
    has violations: int = 0;
}

walker Inspector {
    has stations_visited: int = 0;
    has total_violations: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with Station entry {
        # 1. Temperature check: flag any station above 40 C.
        flag = "VIOLATION" if here.celsius > 40.0 else "OK";
        print(f"[{flag}] {here.name} @ {here.celsius} C");

        # 2. Visit log: every station visit is recorded.
        self.stations_visited += 1;
        if here.celsius > 40.0 {
            here.violations += 1;
            self.total_violations += 1;
        }

        visit [-->];
    }
}

with entry {
    grill = Station(name="Grill", celsius=180.0);
    fryer = Station(name="Fryer", celsius=175.0);
    cold_prep = Station(name="Cold Prep", celsius=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    inspector = Inspector();
    root spawn inspector;

    print(f"Visited {inspector.stations_visited} stations, "
          f"found {inspector.total_violations} violation(s).");
}
