"""Backlog triage: model issue dependencies and tiers as a graph, then walk
the tree to surface a recommended work order. The hand-rolled machinery
the issue complains about (parent/child tracking, manual recursion, ordering
by sibling walks) is replaced by typed edges and a walker that performs
depth-first traversal with explicit cycle protection."""

# Edge archetype: an issue blocks another issue. Carries the tier so
# a walker can prioritise by data-loss severity, not just topology.
edge Blocks {
    has tier: int = 0;
}

# Edge archetype: two issues share a root cause or one fix closes both.
# Used to group "adjacent" issues so they surface together.
edge SharesRootCause {
    has note: str = "";
}

node Issue {
    has title: str = "";
    has severity: int = 0;
    has corrupt: bool = False;
}

walker Triage {
    # Walk the blocking graph tier-by-tier; emit a recommended order.
    # Cycle safety is explicit because walkers in jac 0.36 do not dedupe.
    has current_tier: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        print(f"Backlog triage order (tier {self.current_tier}):");
        visit [-->];
    }

    can triage with Issue entry {
        # Guard against revisiting the same issue via a cyclic blocking edge.
        if here.title in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here.title);
        flag = " [CORRUPT]" if here.corrupt else "";
        print(f"  sev={here.severity}{flag} :: {here.title}");
        visit [-->];
    }
}

# A walker that follows the typed "Blocks" edges to surface dependencies
# from any starting issue. Demonstrates a typed traversal that the issue's
# hand-rolled parent_id recursion would have replaced.
walker FollowBlocking {
    has visited: list[str] = [];

    can start with Root entry {
        # Kick the chain by walking into root's children, which are the
        # entry-point issues for each tier.
        visit [-->];
    }

    can follow with Issue entry {
        if here.title in self.visited {
            # Cycle: the dependency graph closed on itself; stop cleanly.
            print(f"  cycle detected at: {here.title}");
            disengage;
        }
        self.visited.append(here.title);
        print(f"blocks -> {here.title}");
        next_edges = [here->:Blocks:->];
        if next_edges {
            visit next_edges else {
                disengage;
            }
        } else {
            disengage;
        }
    }
}

with entry {
    # Tier 1 — silent corruption / data loss outranks loud failure.
    t1_destructive = Issue(title="destructive paths delete data without reporting", severity=10, corrupt=True);
    t1_merge_discard = Issue(title="merge-then-fail discards conflict records", severity=10, corrupt=True);
    t1_dialog_wipe = Issue(title="dialog guard ignored; dismissed restore still wipes DB", severity=10, corrupt=True);
    t1_bom_consume = Issue(title="finalise consumes whole matched item, ignoring BOM qty", severity=10, corrupt=True);
    t1_restore_swap = Issue(title="restore reports failure after DB already replaced", severity=10, corrupt=True);
    t1_oom = Issue(title="out-of-space never raises storage tier", severity=9);
    t1_timeout_inflight = Issue(title="timeout fires while queued; worker still commits", severity=9);

    # Tier 2 — sync convergence invariants.
    t2_cycle_count = Issue(title="cycle count captured as relative delta; double-counted", severity=9, corrupt=True);
    t2_resolver = Issue(title="collision resolver folds names wider than the index", severity=9, corrupt=True);
    t2_natural_key = Issue(title="missing natural-key collision rule blocks sync", severity=8);
    t2_merge_cycle = Issue(title="merge closes kit containment graph into a cycle", severity=8);

    # Wire blocking relationships (a -> b: a should land before b).
    t1_destructive +>:Blocks(tier=1):+> t1_merge_discard;
    t1_merge_discard +>:Blocks(tier=1):+> t1_dialog_wipe;
    t1_dialog_wipe +>:Blocks(tier=1):+> t1_restore_swap;
    t1_restore_swap +>:Blocks(tier=1):+> t1_bom_consume;
    t1_bom_consume +>:Blocks(tier=1):+> t1_oom;
    t1_oom +>:Blocks(tier=1):+> t1_timeout_inflight;

    t2_cycle_count +>:Blocks(tier=2):+> t2_resolver;
    t2_resolver +>:Blocks(tier=2):+> t2_natural_key;
    t2_natural_key +>:Blocks(tier=2):+> t2_merge_cycle;

    # Shared root-cause groupings.
    t1_dialog_wipe +>:SharesRootCause(note="post-overwrite reporting hazard"):+> t1_restore_swap;
    t2_resolver +>:SharesRootCause(note="natural-key family"):+> t2_natural_key;

    # Mount the backlog under root so the walkers can be spawned on it.
    root ++> t1_destructive ++> t2_cycle_count;

    # Run the tiered triage walker for each tier.
    Triage(current_tier=1) spawn root;
    Triage(current_tier=2) spawn root;

    # Walk the blocking chain from the highest-severity Tier-1 issue.
    print("Following blocking chain from tier-1 entry issue:");
    FollowBlocking() spawn root;
}
