type JsonValue = str | bool | int | float | None;

glob defaultOptions: dict[str, str | bool] = {"delimiter": ",", "quote": "\"", "comment": "#", "useHeaders": True, "skipEmptyLines": True, "dynamicTypes": True};

def parseCsvLine(line: str, options: dict[str, str | bool]) -> list[str] {
    values: list[str] = [];
    currentValue = "";
    inQuotes = False;
    i = 0;
    delimiter = options["delimiter"] as str;
    quote = options["quote"] as str;
    while i < len(line) {
        ch = line[i];
        if ch == quote {
            if inQuotes and i + 1 < len(line) and line[i + 1] == quote {
                currentValue = currentValue + quote;
                i = i + 2;
                continue;
            }
            inQuotes = not inQuotes;
            i = i + 1;
            continue;
        }
        if ch == delimiter and not inQuotes {
            values.append(currentValue.strip());
            currentValue = "";
            i = i + 1;
            continue;
        }
        currentValue = currentValue + ch;
        i = i + 1;
    }
    values.append(currentValue.strip());
    return values;
}

def parseValue(value: str, dynamicTypes: bool) -> JsonValue {
    if not dynamicTypes {
        return value;
    }
    if value.lower() == "true" {
        return True;
    }
    if value.lower() == "false" {
        return False;
    }
    if value == "null" {
        return None;
    }
    try {
        if "." in value {
            return float(value);
        }
        return int(value);
    } except ValueError {
        return value;
    }
}
