"""Dungeon crawler: chained room nodes with a hidden treasure; a Hunter walker
traverses the dungeon, counts rooms visited, and disengages the moment it
finds the vault — no room past the treasure is ever entered."""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        print(f"Entering {here.name}... total rooms checked: {self.rooms_checked}");
        if here.is_vault {
            print(f"Treasure found in {here.name}! Search ends.");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Forbidden Chamber")
        ++> Room(name="Dragon's Lair");

    hunter = Hunter();
    root spawn hunter;
    print(f"Final tally: hunter inspected {hunter.rooms_checked} rooms.");
}
