"""Order auditor: skip invalid orders but halt the walk on fraud."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Beginning order audit");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] amount={here.amount} flagged for fraud — stopping audit");
            disengage;
        } elif not here.valid {
            print(f"[SKIP] amount={here.amount} invalid — continuing");
            visit [-->];
        } else {
            print(f"[AUDIT] amount={here.amount} approved");
            visit [-->];
        }
    }
}

with entry {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=50.0, valid=False, fraud=False)
        ++> Order(amount=200.0, valid=True, fraud=True)
        ++> Order(amount=75.0, valid=True, fraud=False);
    root spawn OrderAuditor();
}
