"""Mutual friendships in a neighborhood.

Houses are nodes linked by typed ``Buddy`` edges created bidirectionally
in a single statement. Two ``Greeter`` walkers are spawned — one from each
end of a friendship — and each proves the link points the other way using
forward traversal alone, with an explicit cycle guard so they cannot bounce
back and forth forever.
"""

node House {
    has name: str = "";
    has visited: bool = False;
}

edge Buddy {
    has since: str = "";
}

walker Greeter {
    has origin: str = "";
    has target: str = "";
    has reached: bool = False;

    can start with Root entry {
        # Seed the visit with the walker's spawn node (House), not root.
        visit [-->];
    }

    can greet with House entry {
        # Mark the current node so the walker cannot bounce forever.
        here.visited = True;
        if here.name == self.target {
            self.reached = True;
            print(f"[{self.origin}] reached buddy house '{here.name}'");
            return;
        }
        # Only keep moving forward along Buddy edges we have not yet
        # burned through, and never re-enter a visited house.
        next_nodes = [];
        for n in [->:Buddy:->] {
            if not n.visited {
                next_nodes.append(n);
            }
        }
        if len(next_nodes) > 0 {
            visit next_nodes;
        } else {
            print(f"[{self.origin}] dead end at '{here.name}'");
            disengage;
        }
    }
}

with entry {
    # Build two houses and link them with a single bidirectional Buddy edge.
    maple = House(name="Maple");
    oak = House(name="Oak");
    maple +>:Buddy(since="2024"):+> oak;
    oak +>:Buddy(since="2024"):+> maple;
    root ++> maple ++> oak;

    # Spawn one greeter at each house; each should reach the other.
    maple_greeter = Greeter(origin="Maple", target="Oak");
    oak_greeter = Greeter(origin="Oak", target="Maple");

    print("--- Greeter spawned at Maple ---");
    maple spawn maple_greeter;
    print(f"Maple greeter reached Oak? {maple_greeter.reached}");

    # Reset visited flags so the second walker can traverse cleanly.
    maple.visited = False;
    oak.visited = False;

    print("--- Greeter spawned at Oak ---");
    oak spawn oak_greeter;
    print(f"Oak greeter reached Maple? {oak_greeter.reached}");
}
