"""Restaurant recommender: walker filters restaurants by minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker DateNightFinder {
    has min_rating: float = 4.5;

    can start with Root entry {
        visit [-->];
    }

    can review with Restaurant entry {
        if here.rating >= self.min_rating {
            print(f"[Date night] {here.name} ({here.cuisine}) — {here.rating}★");
        }
        visit [-->];
    }
}

walker CasualLunchFinder {
    has min_rating: float = 3.5;

    can start with Root entry {
        visit [-->];
    }

    can review with Restaurant entry {
        if here.rating >= self.min_rating {
            print(f"[Casual lunch] {here.name} ({here.cuisine}) — {here.rating}★");
        }
        visit [-->];
    }
}

with entry {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
        ++> Restaurant(name="Sakura", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Bella Trattoria", cuisine="Italian", rating=4.2)
        ++> Restaurant(name="Taco Stand", cuisine="Mexican", rating=3.8)
        ++> Restaurant(name="Diner Express", cuisine="American", rating=3.0);

    root spawn DateNightFinder(min_rating=4.5);
    print("---");
    root spawn CasualLunchFinder(min_rating=3.5);
