import React;
import from "react" {
    useMemo,
    useRef,
    useState,
    useContext,
    createContext,
    isValidElement,
    cloneElement,
    createElement,
    Fragment,
    forwardRef,
    useLayoutEffect,
    useEffect,
}
import from "./use-sync-external-store.js" { useSyncExternalStore }

glob useBuiltinInsertionEffect = React["useInsertion" + "Effect"];

glob:pub useIsomorphicLayoutEffect = React.useLayoutEffect if typeof(window) != "undefined" else React.useEffect;

glob:pub useInsertionEffect = useBuiltinInsertionEffect or useIsomorphicLayoutEffect;

def:pub useEvent(fn: Callable) -> Callable {
    pair = React.useRef(None);
    if pair.current is None {
        def stable(*call_args: object) -> object {
            handler = pair.current[0];
            return handler(*call_args);
        }
        pair.current = [fn, stable];
    }
    useInsertionEffect(lambda {
        pair.current[0] = fn;
    });
    return pair.current[1] as Callable;
}
