import { useEffect } from 'react';

const useDebounce = (fn: () => any, ms: number = 0, args: any[] = []) => {
  useEffect(() => {
    const handle = setTimeout(fn.bind(null, args), ms);

    return () => {
      // if args change then clear timeout
      clearTimeout(handle);
    };
  }, args);
};

export default useDebounce;

```jac
def:pub useDebounce(fn: Callable[[list[object]], object], ms: float = 0, args: list[object] = []) {
    useEffect(lambda {
        handle = setTimeout(lambda { fn(args); }, ms);
        return lambda {
            clearTimeout(handle);
        };
    }, args);
}
