"""Warehouse stock take: shelves hold stock items, a counter walker sweeps and reports per-shelf quantities."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
    has available: bool = True;
}

walker Counter {
    has quantities: list[int] = [];

    can start with Root entry {
        print("Starting warehouse stock take...");
        visit [-->] else { disengage; }
    }

    can sweep with StockItem entry {
