"""Hiking trail: chain of plain waypoints from trailhead to summit.

The waypoints themselves carry no data — they exist purely as nodes
the hiker traverses. The hiker walker counts how many waypoints it
passes, prints each stop number, and emits a completion line once
enough have been visited.
"""

node Waypoint {
    has label: str = "";
}

walker Hiker {
    has stops_made: int = 0;
    has target_stops: int = 5;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can hike with Waypoint entry {
        self.stops_made += 1;
        stop_label = here.label if here.label else f"Stop {self.stops_made}";
        print(f"Stop {self.stops_made}: {stop_label}");
        if self.stops_made >= self.target_stops {
            print(f"Trail complete! Visited {self.stops_made} waypoints.");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    (root ++> Waypoint(label="Trailhead")
        ++> Waypoint(label="Creek Crossing")
        ++> Waypoint(label="Meadow Overlook")
        ++> Waypoint(label="Rocky Ledge")
        ++> Waypoint(label="Pine Grove")
        ++> Waypoint(label="Summit"));
    root spawn Hiker(target_stops=6);
}
