obj CooperationPersonStore {
    has persons: list[str] = [];

    def addPersons(newPersons: list[str]) {
        self.persons = list(set(self.persons + newPersons));
    }

    def removePersons(personsToRemove: list[str]) {
        self.persons = [id for id in self.persons if id not in personsToRemove];
    }

    def getPersons() -> list[str] {
        return self.persons;
    }

    def setPersons(persons: list[str]) {
        self.persons = persons;
    }
}

glob _useCooperationPersonStore: CooperationPersonStore = CooperationPersonStore();

def useCooperationPerson() -> CooperationPersonStore {
    return _useCooperationPersonStore;
}
