def:pub validateEmail(email: str) -> bool {
    api_key = os.environ.get("ZEROBOUNCE_API_KEY");
    if not api_key {
        return True;
    }
    url = f"https://api.zerobounce.net/v2/validate?api_key={api_key}&email={email}&ip_address=";
    resp = urllib.request.urlopen(url);
    raw_text = resp.read().decode();
    resp.close();
    response_data = json.loads(raw_text) as dict[str, str | bool | None];
    status = str(response_data.get("status", ""));
    switch status {
        case "invalid":
        case "spamtrap":
        case "abuse":
        case "do_not_mail":
            return False;
        default:
            break;
    }
    return True;
}
