"""Bug tracker: file tickets off a project node and capture each fresh ticket inline."""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "low";
}

edge Filed {
    has filed_at: str = "";
}

walker Triage {
    can start with Root entry {
        visit [-->];
    }

    can review with Project entry {
        print(f"Project: {here.name}");
        visit [-->];
    }

    can file with Ticket entry {
        print(f"  - [{here.priority}] {here.title}");
        visit [-->];
    }
}

with entry {
    root ++> Project(name="Website Redesign");

    fresh_a = (root +>:Filed:+> Ticket(title="Broken login button", priority="high"));
    fresh_b = (root +>:Filed:+> Ticket(title="Typo on landing page", priority="low"));
    fresh_c = (root +>:Filed:+> Ticket(title="Checkout crashes on Safari", priority="critical"));

    print("Newly filed tickets:");
    for t in [fresh_a, fresh_b, fresh_c] {
        if t is not None {
            print(f"  - [{t.priority}] {t.title}");
        }
    }

    print("Walking the tracker:");
    root spawn Triage();
}
