type CacheValue = str | int | bool;
type CacheEntry = tuple[str, str];

glob cache: dict[str, str] = {};

def:pub get(property: str, value: CacheValue, selectorHead: str = "") -> str | None {
    return cache.get(selectorHead + property + str(value));
}

def:pub set(property: str, value: CacheValue, className: str, selectorHead: str = "") {
    cache[selectorHead + property + str(value)] = className;
}

def:pub entries() -> list[CacheEntry] {
    return list(cache.items());
}

def:pub hydrate(newEntries: list[CacheEntry]) {
    for (k, v) in newEntries {
        cache[k] = v;
    }
}

def:pub clear() {
    cache.clear();
}
