"""Warehouse stock take: walk shelf nodes and report quantities."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    has total: int = 0;
    has smallest: int = 0;
    has first: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can sweep with StockItem entry {
        report {
            "sku": here.sku,
            "quantity": here.quantity
        };
        self.total = self.total + here.quantity;
        if self.first {
            self.smallest = here.quantity;
            self.first = False;
        } else {
            low = here.quantity if here.quantity < self.smallest else self.smallest;
            self.smallest = low;
        }
        visit [-->];
    }
}

with entry {
    root ++> StockItem(sku="A-001", quantity=42)
        ++> StockItem(sku="A-002", quantity=17)
        ++> StockItem(sku="B-104", quantity=8)
        ++> StockItem(sku="C-220", quantity=25);

    counter = Counter();
    result = root spawn counter;

    print("Per-item counts:");
    for entry in result.reports {
        print(f"  {entry['sku']}: {entry['quantity']}");
    }
    print(f"Total units: {counter.total}");
    print(f"Smallest shelf count: {counter.smallest}");
}
