import from libs.components.src.root.vars { ROOT_DATA }

obj:pub HorizontalSidePosition {
    has top: float;
    has left: float;
    has transformOrigin: str;
}

obj PopupSize {
    has width: float;
    has height: float;
}

obj HorizontalSideConfig {
    has placement: str;
    has gap: float = 10;
    has inWindow: float | bool = False;
}

def:pub getHorizontalSidePosition(
    targetEl: HTMLElement,
    popupSize: PopupSize,
    config: HorizontalSideConfig
) -> HorizontalSidePosition {
    width = popupSize.width;
    height = popupSize.height;
    placement = config.placement;
    gap = config.gap;
    inWindow = config.inWindow;

    targetRect = targetEl.getBoundingClientRect();

    top = targetRect.top;
    if inWindow is not False {
        margin = inWindow as float;
        top = min(max(top, margin), ROOT_DATA.windowSize.height - height - margin);
    }
    if placement == "right" {
        left = targetRect.left + targetRect.width + gap;
    } else {
        left = targetRect.left - width - gap;
    }
    if inWindow is not False {
        margin = inWindow as float;
        left = min(max(left, margin), ROOT_DATA.windowSize.width - width - margin);
    }

    centerY = min(targetRect.top - top + targetRect.height / 2, height);
    if placement == "right" {
        transformOrigin = f"left {centerY}px";
    } else {
        transformOrigin = f"right {centerY}px";
    }

    return HorizontalSidePosition(top=top, left=left, transformOrigin=transformOrigin);
}
