import from "clsx" { clsx }

def:pub Popup(
    prefixCls: str | None = None,
    children: Callable[[], JsxElement] | JsxElement | str | int | None = None,
    id: str | None = None,
    classNames: dict[str, str] | None = None,
    styles: dict[str, dict[str, object]] | None = None,
    className: str | None = None,
    style: dict[str, object] | None = None,
) -> JsxElement {
    container_cls = classNames?.["container"] if classNames else None;
    container_style = styles?.["container"] if styles else None;
    merged_style: dict[str, object] = {};
    if container_style {
        merged_style = {**merged_style, **container_style};
    }
    if style {
        merged_style = {**merged_style, **style};
    }
    content: JsxElement | str | int | None = None;
    if callable(children) {
        fn = children as Callable[[], JsxElement];
        content = fn();
    } else {
        content = children;
    }
    <div
        id={id if id else ""}
        className={clsx(f"{prefixCls}-container", container_cls, className)}
        style={merged_style}
        role="tooltip"
    >
        {content}
    </div>
}
