import from os.path { dirname, exists, join, relpath }
import from core.lib.logging { logGeneralError }
import from core.lib.util.toArray { toArray }
import type from core.types { TwinConfig }

def getFirstValue[ListItem](
    list: list[ListItem],
    getValue: Callable[[ListItem, dict[str, bool | int]], bool | str | int | None],
) -> tuple[bool | str | int | None, ListItem | None] {
    firstValue: bool | str | int | None = None;
    listLength = len(list) - 1;
    listItem: ListItem | None = None;
    for (index, item) in enumerate(list) {
        isLast = index == listLength;
        firstValue = getValue(item, {"index": index, "isLast": isLast});
        if firstValue {
            listItem = item;
            break;
        }
    }
    return (firstValue, listItem);
}

def checkExists(fileName: str | list[str], srcRoot: str) -> str | None {
    (_, value) = getFirstValue(
        toArray(fileName) as list[str],
        lambda (existingFileName: str, _options: dict[str, bool | int]) -> bool {
            return exists(join(srcRoot, f"./{existingFileName}"));
        },
    );
    return value;
}

def getRelativePath(comparePath: str, filename: str) -> str {
    pathName = dirname(filename);
    return relpath(comparePath, pathName);
}

def getStitchesPath(
    sourceRoot: str | None,
    filename: str,
    config: TwinConfig,
) -> str {
    srcRoot = sourceRoot if sourceRoot is not None else ".";
    configPathCheck: str | list[str] = (
        config.stitchesConfig
        if config.stitchesConfig is not None
        else ["stitches.config.ts", "stitches.config.js"]
    );
    configPath = checkExists(configPathCheck, srcRoot);
    if configPath is None {
        location = (
            f'"{config.stitchesConfig}"'
            if config.stitchesConfig is not None
            else "the project root"
        );
        msg = logGeneralError(
            f"Couldn't find the Stitches config at {location}.\nUse the twin config: stitchesConfig=\"PATH_FROM_PROJECT_ROOT\" to set the location.",
        );
        raise Exception(msg);
    }
    return getRelativePath(configPath, filename);
}
