    has rightContent: object | None = None;
    has children: object | None = None;
    has icon: object | None = None;
    has onLeftClick: Callable[[MouseEvent], None] | None = None;
    has mode: str = "dark";
    has title: object | None = None;
    has fixed: bool = False;
    has placeholder: bool = False;
    has zIndex: int = 9;
    has style: dict[str, object] | None = None;
