def:pub navbar(
    title: object | None = None,
    onLeftClick: Callable[[MouseEvent], None] | None = None,
    leftContent: object | None = None,
    rightContent: object | None = None,
    icon: object | None = None,
    children: object | None = None,
    mode: str = "dark",
    fixed: bool = False,
    placeholder: bool = False,
    zIndex: int = 9,
    className: str | None = None,
    style: dict[str, object] | None = None,
) -> JsxElement {
    wrapCls = classnames(prefixCls, className, f"{prefixCls}-{mode}", {f"{prefixCls}-fixed": fixed});
    barStyle = {**style, "zIndex": zIndex if fixed else 0} if style else {"zIndex": zIndex if fixed else 0};
    def handle_left_click(e: MouseEvent) {
        if onLeftClick {
            onLeftClick(e);
        }
    }
    return <>
        <div className={wrapCls} style={barStyle}>
            <div className={f"{prefixCls}-left"} role="button" onClick={handle_left_click}>
                {if icon {
                    <span className={f"{prefixCls}-left-icon"} aria-hidden="true">{icon}</span>
                }}
                {leftContent}
            </div>
            <div className={f"{prefixCls}-title"}>{children if children else title}</div>
            <div className={f"{prefixCls}-right"}>{rightContent}</div>
        </div>
        {if placeholder and fixed {
            <div className={f"{prefixCls}-placeholder"} />
        }}
    </>;
}
