"""Build system dependency auditor: traverses a diamond-shaped task graph
once per node, summing build minutes across all tasks."""

node Task {
    has name: str = "";
    has minutes: int = 0;
}

walker Auditor {
    has total_minutes: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            self.total_minutes = self.total_minutes + here.minutes;
            print(f"Audited {here.name} (+{here.minutes} min)");
            visit [-->];
        } else {
            print(f"Skipped duplicate {here.name}");
            disengage;
        }
    }
}

with entry {
    # Diamond: root -> A and root -> B both depend on shared_lib
    shared_lib = Task(name="shared_lib", minutes=5);
    a = Task(name="module_a", minutes=10);
    b = Task(name="module_b", minutes=8);
    linker = Task(name="linker", minutes=12);
    root ++> a ++> shared_lib;
    root ++> b ++> shared_lib;
    root ++> linker;
    root spawn Auditor();
}
