import asyncio;
import json;
import urllib.parse;
import urllib.request;

type Method = Literal["GET", "POST", "PUT", "DELETE", "PATCH"];

obj Params {
    has cacheTime: int | None = None;
    has params: dict[str, object] | None = None;
}

obj RequestProps {
    has url: str;
    has method: Method;
    has cacheTime: int | None = None;
    has params: dict[str, object] | None = None;
    has mode: str | None = None;
    has token: str | None = None;
}

obj HttpPayload {
    has url: str;
    has method: Method;
    has headers: dict[str, str];
    has body: str | None = None;
}

def buildQueryString(params: dict[str, object]) -> str {
    return urllib.parse.urlencode({k: str(v) for (k, v) in params.items()});
}

async def performRequest(payload: HttpPayload) -> tuple[int, str, str] {
    def doRequest() -> tuple[int, str, str] {
        data = payload.body.encode() if payload.body is not None else None;
        req = urllib.request.Request(
            payload.url,
            data=data,
            headers=payload.headers,
            method=payload.method
        );
        resp = urllib.request.urlopen(req);
        status = resp.status;
        finalUrl = resp.url;
        text = resp.read().decode();
        resp.close();
        return (status, finalUrl, text);
    }
    return await asyncio.to_thread(doRequest);
}

obj Request {
    has baseURL: str;

    def interceptorsRequest(props: RequestProps) -> HttpPayload {
        headers: dict[str, str] = {};
        url: str = props.url;
        method: Method = props.method;
        body: str | None = None;

        if props.token is not None {
            headers["Authorization"] = f"Bearer {props.token}";
        }

        if method == "GET" or method == "DELETE" {
            if props.params is not None {
                url = f"{url}?{buildQueryString(props.params)}";
            }
        } elif props.params is not None {
            headers["Content-Type"] = "application/json";
            body = json.dumps(props.params);
        }

        return HttpPayload(url=url, method=method, headers=headers, body=body);
    }

    async def interceptorsResponse[T](status: int, requestUrl: str, text: str) -> T {
        if status >= 200 and status < 300 {
            return json.loads(text) as T;
        }
        try {
            errorData = json.loads(text);
            raise ValueError(f"{str(errorData)}@{requestUrl}");
        } except json.JSONDecodeError {
            raise ValueError(f"{text}@{requestUrl}");
        }
    }

    async def httpFactory[T](
        url: str = "",
        params: Params | None = None,
        method: Method = "GET",
        mode: str | None = None,
        token: str | None = None
    ) -> T {
        p = params if params is not None else Params();
        payload = self.interceptorsRequest(RequestProps(
            url=self.baseURL + url,
            method=method,
            params=p.params,
            cacheTime=p.cacheTime,
            mode=mode,
            token=token
        ));
        (status, finalUrl, text) = await performRequest(payload);
        return await self.interceptorsResponse[T](status, finalUrl, text);
    }

    async def request[T](
        method: Method,
        url: str,
        params: Params | None = None,
        mode: str | None = None,
        token: str | None = None
    ) -> T {
        return await self.httpFactory[T](url=url, params=params, method=method, mode=mode, token=token);
    }

    async def get[T](
        url: str,
        params: Params | None = None,
        mode: str | None = None,
        token: str | None = None
    ) -> T {
        return await self.request[T]("GET", url, params, mode, token);
    }

    async def post[T](
        url: str,
        params: Params | None = None,
        mode: str | None = None,
        token: str | None = None
    ) -> T {
        return await self.request[T]("POST", url, params, mode, token);
    }

    async def put[T](
        url: str,
        params: Params | None = None,
        mode: str | None = None,
        token: str | None = None
    ) -> T {
        return await self.request[T]("PUT", url, params, mode, token);
    }

    async def delete[T](
        url: str,
        params: Params | None = None,
        mode: str | None = None,
        token: str | None = None
    ) -> T {
        return await self.request[T]("DELETE", url, params, mode, token);
    }

    async def patch[T](
        url: str,
        params: Params | None = None,
        mode: str | None = None,
        token: str | None = None
    ) -> T {
        return await self.request[T]("PATCH", url, params, mode, token);
    }
}
