def:pub useSetState(initialState: dict[str, object] = {}) -> list[object] {
    state_data = useState(initialState);
    state: dict[str, object] = state_data[0] as dict[str, object];
    set: Callable[[Callable[[dict[str, object]], dict[str, object]]], None] = state_data[1] as Callable[[Callable[[dict[str, object]], dict[str, object]]], None];
    setState = lambda (patch: object) {
        set(lambda (prevState: dict[str, object]) {
            if callable(patch) {
                return mergeObjects(prevState, (patch as Callable[[dict[str, object]], dict[str, object]])(prevState));
