const compPrefix = `${prefix}-modal`;
export interface ModalAction {
  label: string
  onClick: () => void
}

interface ModalHeaderConfig {
  modalTitle: string
  layout?: 'horizontal' | 'vertical'
  modalSubtitle?: string
  icon?: JSX.Element
}

