"""Static-library link requirement propagation across package dependencies.

Models the essential scenario from the issue: a binary depends on wrapper
packages that own native static archives and link metadata. A walker descends
the dependency graph, harvests each wrapper's typed link requirements, and
merges them in dependency-declaration order so static-linker ordering is
preserved. Diagnostics name the declaring package for each requirement.
"""

node Package {
    has name: str = "";
    has kind: str = "binary";
}

node StaticLib {
    has name: str = "";
    has libs: list[str] = [];
    has search_paths: list[str] = [];
    has args: list[str] = [];
}

edge DependsOn {
    has declared_by: str = "";
}

edge HasLib {
    has search_path: str = "";
}

walker LinkPlanner {
    has ordered_libs: list[str] = [];
    has ordered_paths: list[str] = [];
    has ordered_args: list[str] = [];
    has provenance: dict[str, str] = {};

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can descend with Package entry {
        visit [->:DependsOn:->];
    }

    can harvest with StaticLib entry {
        lib_label = "";
        for lib in here.libs {
            lib_label = lib;
            if lib_label not in self.ordered_libs {
                self.ordered_libs.append(lib_label);
                self.provenance[lib_label] = here.name;
            }
        }
        for path in here.search_paths {
            path_label = path;
            if path_label not in self.ordered_paths {
                self.ordered_paths.append(path_label);
            }
        }
        arg_label = "";
        for arg in here.args {
            arg_label = arg;
            if arg_label not in self.ordered_args {
                self.ordered_args.append(arg_label);
                self.provenance[arg_label] = here.name;
            }
        }
        visit [->:HasLib:->];
    }
}

walker LinkDiagnostics {
    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can descend with Package entry {
        visit [->:DependsOn:->];
    }

    can probe with StaticLib entry {
        missing = "raylib";
        if missing in here.libs {
            print(f"missing native lib '{missing}' from wrapper "
                  f"'{here.name}' (declared in its (link ...))");
        }
        visit [->:HasLib:->];
    }
}

with entry {
    sqlite_wrapper = StaticLib(
        name="sqlite-wrapper",
        libs=["sqlite3", "m"],
        search_paths=["vendor/sqlite/lib", "vendor/os/lib"],
        args=["-lpthread"]
    );

    raylib_wrapper = StaticLib(
        name="raylib-wrapper",
        libs=["raylib", "m"],
        search_paths=["vendor/raylib/lib"],
        args=["-ldl", "-lpthread"]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> sqlite_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> raylib_wrapper;
    sqlite_wrapper +>:HasLib(search_path="vendor/sqlite/lib"):+> StaticLib(name="sqlite-archive");
    raylib_wrapper +>:HasLib(search_path="vendor/raylib/lib"):+> StaticLib(name="raylib-archive");

    planner = LinkPlanner();
    root spawn planner;

    print("Effective ordered link plan for app-binary:");
    print(f"  libs      = {planner.ordered_libs}");
    print(f"  paths     = {planner.ordered_paths}");
    print(f"  args      = {planner.ordered_args}");

    diag = LinkDiagnostics();
    root spawn diag;
}
