"""Delivery route dispatcher: walk depots and report routes within the 2-8 tonne dispatch window."""

node Depot {
    has name: str = "";
}

node Route {
    has destination: str = "";
    has cargo_tonnes: float = 0.0;

    def qualifies() -> bool {
        return self.cargo_tonnes >= 2.0 and self.cargo_tonnes <= 8.0;
    }
}

walker Dispatcher {
    has dispatched: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hub with Depot entry {
        print(f"Checking routes from depot {here.name}");
        visit [-->];
    }

    can screen with Route entry {
        verdict = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"  [{verdict}] {here.destination}: {here.cargo_tonnes}t");
        if here.qualifies() {
            self.dispatched += 1;
        }
        visit [-->];
    }
}

with entry {
    north = Depot(name="North");
    south = Depot(name="South");
    east = Depot(name="East");

    north ++> Route(destination="Riverside", cargo_tonnes=3.5)
        ++> Route(destination="Hilltop", cargo_tonnes=7.8)
        ++> Route(destination="Quarry", cargo_tonnes=9.2)
        ++> Route(destination="Lakeside", cargo_tonnes=1.5);

    south ++> Route(destination="Harbor", cargo_tonnes=5.0)
        ++> Route(destination="Mills", cargo_tonnes=8.0)
        ++> Route(destination="Docks", cargo_tonnes=2.0);

    east ++> Route(destination="Airport", cargo_tonnes=4.2)
        ++> Route(destination="Junction", cargo_tonnes=10.0)
        ++> Route(destination="Outpost", cargo_tonnes=6.7);

    root ++> north ++> south ++> east;

    d = Dispatcher();
    root spawn d;
    print(f"\nTotal routes cleared for dispatch: {d.dispatched}");
}
