import type from stream { OutputStream }

type WindowSize = dict[str, int];

def resolveDimension(value: int | None, fallback: int | None, defaultValue: int) -> int {
    if (value is not None) and (value > 0) {
        return value;
    }
    if (fallback is not None) and (fallback > 0) {
        return fallback;
    }
    return defaultValue;
}

def getWindowSize(stdout: OutputStream) -> WindowSize {
    columns = stdout?.columns or 0;
    rows = stdout?.rows or 0;
    if columns and rows {
        return {"columns": columns, "rows": rows};
    }
    fallbackSize = terminalSize();
    return {
        "columns": resolveDimension(columns if columns else None, fallbackSize?.columns, 80),
        "rows": resolveDimension(rows if rows else None, fallbackSize?.rows, 24),
    };
}
