"""Tiny dungeon crawler: chained room nodes with a treasure vault.

A Hunter walker visits rooms one by one, counting each entry. As soon
as it enters the vault, the search ends — no rooms past the vault are
ever stepped into.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_visited: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        self.rooms_visited += 1;
        print(f"[{self.rooms_visited}] Entering {here.name}");
        if here.is_vault {
            print(f"Treasure found in {here.name}! Hunt ends.");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    antechamber = Room(name="Antechamber");
    hall = Room(name="Hall of Echoes");
    armory = Room(name="Armory");
    vault = Room(name="Vault", is_vault=True);
    cavern = Room(name="Hidden Cavern");

    root ++> antechamber
        ++> hall
        ++> armory
        ++> vault
        ++> cavern;

    h = Hunter();
    root spawn h;

    print(f"Total rooms entered: {h.rooms_visited}");
}
