def isToolCallBlock(block: any) -> bool {
    kind = (block.type if isinstance(block.type, str) else "").lower();
    return ((kind in ["toolcall", "tool_call", "tooluse", "tool_use", "functioncall", "function_call"]) or (isinstance(block.name, str) and ((block.arguments != None) or (block.input != None))));
}

def isToolResultBlock(block: any) -> bool {
    kind = (block.type if isinstance(block.type, str) else "").lower();
    return (kind in ["toolresult", "tool_result"]);
}

def getToolCallId(block: any) -> str {
    if (isinstance(block.id, str) and block.id) {
        return block.id;
    }
    if (isinstance(block.toolCallId, str) and block.toolCallId) {
        return block.toolCallId;
    }
    if (isinstance(block.tool_call_id, str) and block.tool_call_id) {
        return block.tool_call_id;
    }
    return "";
}

def getToolResultCallId(block: any) -> str {
    if (isinstance(block.tool_use_id, str) and block.tool_use_id) {
        return block.tool_use_id;
    }
    if (isinstance(block.toolCallId, str) and block.toolCallId) {
        return block.toolCallId;
    }
    if (isinstance(block.tool_call_id, str) and block.tool_call_id) {
        return block.tool_call_id;
    }
    if (isinstance(block.id, str) and block.id) {
        return block.id;
    }
    return "";
}

