import { useEffect, useState } from 'react';

import { Notification } from '../../interfaces/notification';
import { isExpiredDate } from '../../utils/calcCreatedToCurrentTime';
import NotificationMsg from './NotificationMsg';

const FOLLOW = 'follow';

