import from shared.lib.Queue { Queue }

def createDebouncedHandler(
    eventQueueHandler: Callable[[Queue], None],
    delayInMilliseconds: int = 100
) -> Callable[[object], None] {
    queue = Queue();
    timeout: object | None = None;

    def deobuncedEventHandler(event: object) {
        if timeout is not None {
            clearTimeout(timeout);
        }
        queue.enqueue(event);
        timeout = setTimeout(lambda {
            eventQueueHandler(queue);
            queue.clear();
        }, delayInMilliseconds) as object;
    }
    return deobuncedEventHandler;
}

glob:pub default = createDebouncedHandler;
