obj MinifyJsonResult {
    has result: str;
    has format: JsonFormat;
}

def:pub minifyJson(text: str) -> MinifyJsonResult {
    parsed = parseJsonInput(text);
    data = parsed.data;
    format = parsed.format;
    if (format == "jsonl") and isinstance(data, list) {
        return MinifyJsonResult(
            result="\n".join([json.dumps(item) for item in data]),
            format=format
        );
    }
    return MinifyJsonResult(result=json.dumps(data), format=format);
}
