  highlight: chalk.yellowBright,
  subdued: chalk.hex('#999'),
}

function makeColor(hasColor: boolean): MakeColor {
  return (message: string, type: keyof typeof colors = 'error') => {
    if (!hasColor) return message
    return colors[type](message)
  }
}

