        <DialogClose asChild>
          <Button variant="cancel" size="sm" onClick={handleCancel}>
            Cancel
          </Button>
        </DialogClose>
        <Button
          variant="danger"
          size="sm"
          onClick={handleDelete}
          disabled={!isChecked || isLoading}
        >
          Delete
        </Button>
      </DialogFooter>
    </DialogContent>
  );
};

