glob _BUTTON_BASE: str = "inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50";

glob _BUTTON_VARIANTS: dict[str, str] = {
    "default": "bg-primary text-primary-foreground hover:bg-primary/90",
    "destructive": "bg-destructive text-destructive-foreground hover:bg-destructive/90",
    "outline": "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
    "secondary": "bg-secondary text-secondary-foreground hover:bg-secondary/80",
    "ghost": "hover:bg-accent hover:text-accent-foreground",
    "link": "text-primary underline-offset-4 hover:underline",
};

glob _BUTTON_SIZES: dict[str, str] = {
    "default": "h-10 px-4 py-2",
    "sm": "h-9 rounded-md px-3",
    "lg": "h-11 rounded-md px-8",
    "icon": "h-10 w-10",
};

def:pub buttonVariants(options: dict[str, str] = {}) -> str {
    variant = options["variant"] if "variant" in options else "default";
    size = options["size"] if "size" in options else "default";
    className = options["className"] if "className" in options else "";
    variantClass = _BUTTON_VARIANTS[variant] if variant in _BUTTON_VARIANTS else _BUTTON_VARIANTS["default"];
    sizeClass = _BUTTON_SIZES[size] if size in _BUTTON_SIZES else _BUTTON_SIZES["default"];
    return cn(_BUTTON_BASE, variantClass, sizeClass, className);
}

def:pub Button(
    className: str = "",
    variant: str = "default",
    size: str = "default",
    asChild: bool = False,
    ref: Ref = Ref(),
    props: dict[str, object] = {}
) -> JsxElement {
    computedClass = buttonVariants({"variant": variant, "size": size, "className": className});
    if asChild {
        return <Slot className={computedClass} ref={ref} {**props} />;
    }
    <button className={computedClass} ref={ref} {**props} />
}
