def:pub getDimensionsFromFreeDraw(params: dict) -> dict[str, object] {
    freeDrawObject = params["freeDrawObject"];
    positionFromDrawingPoints = getPositionFromDrawingPoints({"freeDrawPoints": freeDrawObject["freeDrawPoints"]});
    freeDrawPoints = freeDrawObject["freeDrawPoints"];
    posX = positionFromDrawingPoints["x"] as float;
    objX = freeDrawObject["x"] as float;
    objY = freeDrawObject["y"] as float;
    posY = positionFromDrawingPoints["y"] as float;
    x = (((Math.min(*[p["x"] as float for p in freeDrawPoints]) + objX) - posX) or 0);
    y = (((Math.min(*[p["y"] as float for p in freeDrawPoints]) + objY) - posY) or 0);
    width = (Math.max(*[p["x"] as float for p in freeDrawPoints]) - Math.min(*[p["x"] as float for p in freeDrawPoints]));
    height = (Math.max(*[p["y"] as float for p in freeDrawPoints]) - Math.min(*[p["y"] as float for p in freeDrawPoints]));
    return {"x": x, "y": y, "width": width, "height": height};
}
