                set(lambda (state: dict[str, object]) { return persistAuth(auth); });
            },
            "getAuth": lambda -> dict[str, object] { return get(); },
            "logout": lambda (cb: Callable | None) -> None {
                set(lambda (state: dict[str, object]) {
