"""Journal share-link grant toggle.

Demonstrates a walker that arms a READ grant on a note (so anyone with the
link can read it), and another walker that revokes the grant, returning
the note to owner-only access. A flag on the note itself surfaces the
transition in the printed output.
"""

node Note {
    has title: str = "";
    has body: str = "";
    has owner: str = "";
    has shared: bool = False;
}

walker GrantRead {
    has reader: str = "";

    can start with Root entry {
        visit [-->];
    }

    can arm with Note entry {
        here.shared = True;
        print(f"[GRANT] {here.title} is now shared (READ) "
              f"for {self.reader} | shared={here.shared}");
        visit [-->];
    }
}

walker RevokeRead {
    can start with Root entry {
        visit [-->];
    }

    can disarm with Note entry {
        here.shared = False;
        print(f"[REVOKE] {here.title} returned to owner-only "
              f"| shared={here.shared}");
        visit [-->];
    }
}

with entry {
    n1 = Note(title="Morning Pages", body="...", owner="alex");
    n2 = Note(title="Trip Recap", body="...", owner="alex");
    n3 = Note(title="Book List", body="...", owner="alex");
    root ++> n1 ++> n2 ++> n3;

    print("--- before grant ---");
    print(f"{n1.title} shared={n1.shared}");
    print(f"{n2.title} shared={n2.shared}");
    print(f"{n3.title} shared={n3.shared}");

    root spawn GrantRead(reader="bob");
    root spawn RevokeRead();

    print("--- after revoke ---");
    print(f"{n1.title} shared={n1.shared}");
    print(f"{n2.title} shared={n2.shared}");
    print(f"{n3.title} shared={n3.shared}");
}
