"""Gallery security console: generic visitor logging plus curator inspections."""

node Room {
    has name: str = "";
    has log: list[str] = [];
}

walker Visitor {
    has visitor_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"visitor: {self.visitor_name}");
        print(f"{self.visitor_name} logged into {here.name}");
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"curator: {self.curator_name}");
        here.log.append(f"official inspection by {self.curator_name}");
        self.inspections += 1;
        print(f"{self.curator_name} performed an official inspection in {here.name}");
        visit [-->];
    }
}

walker Tourist {
    has tourist_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can visit with Room entry {
        here.log.append(f"visitor: {self.tourist_name}");
        print(f"{self.tourist_name} logged into {here.name}");
        visit [-->];
    }
}

with entry {
    lobby = Room(name="Lobby");
    gallery = Room(name="Gallery");
    root ++> lobby ++> gallery;

    # Generic visitor (no specialization) — gets only the base log entry.
    generic = Visitor(visitor_name="Alex");
    root spawn generic;

    # Tourist — a flavor of visitor, also just logs.
    tourist = Tourist(tourist_name="Sam");
    root spawn tourist;

    # Curator — logs AND records an official inspection.
    curator = Curator(curator_name="Dr. Lee");
    root spawn curator;

    print("");
    print(f"Lobby log: {lobby.log}");
    print(f"Gallery log: {gallery.log}");
    print(f"Curator {curator.curator_name} performed {curator.inspections} inspection(s)");
}
