import from "@base-ui/react/dialog" { Dialog as SheetPrimitive }
import from "lucide-react" { X }
import from "@/lib/utils" { cn }

glob:pub Sheet = SheetPrimitive.Root;

glob:pub SheetTrigger = SheetPrimitive.Trigger;

glob SheetPortal = SheetPrimitive.Portal;

def sheetVariants(side: str = "right") -> str {
    base = "fixed z-[60] gap-4 overscroll-contain border-border bg-background p-6 shadow-lg transition-transform duration-300 ease-[cubic-bezier(0.32,0.72,0,1)] motion-reduce:transition-none data-ending-style:duration-200";
    side_classes: dict[str, str] = {
        "top": "inset-x-0 top-0 border-b data-starting-style:-translate-y-full data-ending-style:-translate-y-full",
        "bottom": "inset-x-0 bottom-0 border-t data-starting-style:translate-y-full data-ending-style:translate-y-full",
        "left": "inset-y-0 left-0 h-full w-3/4 border-r data-starting-style:-translate-x-full data-ending-style:-translate-x-full sm:max-w-sm",
        "right": "inset-y-0 right-0 h-full w-3/4 border-l data-starting-style:translate-x-full data-ending-style:translate-x-full sm:max-w-sm",
    };
    return cn(base, side_classes.get(side, side_classes["right"]));
}

def:pub SheetOverlay(className: str | None = None, rest: dict[str, object] = {}) -> JsxElement {
    <SheetPrimitive.Backdrop
        className={cn(
            "fixed inset-0 z-[60] bg-black/80 transition-opacity duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none data-starting-style:opacity-0 data-ending-style:opacity-0",
            className
        )}
        {**rest}
    />
}
