import axios;
import from "./config" { BASE_URL }
import from "./types/Api" { GenericResponse }
import from "./types/AuthAPI" { LoginInput, LoginResponse, LogoutResponse, RefreshTokenResponse, RegisterInput, ResetPasswordInput }

async def:pub refreshAccessToken() -> RefreshTokenResponse {
    response = await axios.get(f"{BASE_URL}/auth/refresh-token", {"withCredentials": True});
    return response.data.data as RefreshTokenResponse;
}

async def:pub loginUser(data: LoginInput) -> LoginResponse {
    response = await axios.post(f"{BASE_URL}/auth/sign", data, {"withCredentials": True});
    return response.data.data as LoginResponse;
}

async def:pub registerUser(data: RegisterInput) -> LoginResponse {
    response = await axios.post(f"{BASE_URL}/auth/register", data, {"withCredentials": True});
    return response.data.data as LoginResponse;
}

async def:pub logoutUser() -> str {
    response = await axios.delete(f"{BASE_URL}/auth/logout", {"withCredentials": True});
    return response.data.message as str;
}

async def:pub getUser() -> dict[str, object] {
    response = await axios.get(f"{BASE_URL}/auth/user", {"withCredentials": True});
    return response.data.data as dict[str, object];
}

async def:pub forgotPassword(email: str) -> GenericResponse {
    response = await axios.post(f"{BASE_URL}/auth/forgot-password", {"email": email}, {"withCredentials": True});
    return response.data as GenericResponse;
}

async def:pub verifyResetPasswordToken(token: str) -> dict[str, object] {
    response = await axios.get(f"{BASE_URL}/auth/reset-password?token={token}", {"withCredentials": True});
    return response.data.data as dict[str, object];
}

async def:pub resetPassword(data: ResetPasswordInput) -> str {
    response = await axios.post(f"{BASE_URL}/auth/reset-password", data, {"withCredentials": True});
    return response.data.message as str;
}

async def:pub loginWithGoogleCode(code: str) -> dict[str, object] {
    response = await axios.post(f"{BASE_URL}/auth/login-with-google", {"code": code}, {"withCredentials": True});
    return response.data as dict[str, object];
}
