      expect(
        isAllowedUploadUrl(
          'https://my-bucket.s3.eu-central-1.amazonaws.com/receipts/1.png',
        ),
      ).toBe(true)
    })

    it('rejects the same bucket in a different region', () => {
      expect(
        isAllowedUploadUrl(
          'https://my-bucket.s3.us-east-1.amazonaws.com/receipts/1.png',
        ),
      ).toBe(false)
    })

    it('rejects an unrelated host', () => {
