import from "../../useNinetailed" { useNinetailed }

obj DomEl {
    has nextElementSibling: DomEl | None = None;
    has parentElement: DomEl | None = None;
}

obj MarkerEl {
    has style: InlineStyle;
    has nextElementSibling: DomEl | None = None;
    has parentElement: DomEl | None = None;
}

obj InlineStyle {
    def setProperty(name: str, value: str, priority: str) -> None;
}

obj CssComputed {
    has display: str = "";
}

obj NinetailedLogger {
    def debug(message: str) -> None;
}

obj NinetailedCtx {
    has logger: NinetailedLogger;
}

def getObservableSibling(element: DomEl) -> DomEl | None {
    nextSibling = element.nextElementSibling;
    if not nextSibling {
        return None;
    }
    nextSiblingStyle: CssComputed = getComputedStyle(nextSibling) as CssComputed;
    if nextSiblingStyle.display != "none" {
        return nextSibling;
    }
    return getObservableSibling(nextSibling);
}

def getObservableElement(element: DomEl) -> DomEl | None {
    observableSibling = getObservableSibling(element);
    if observableSibling {
        return observableSibling;
    }
    parentElement = element.parentElement;
    if not parentElement {
        return None;
    }
    return getObservableElement(parentElement);
}

def:pub ComponentMarker(ref: Ref[DomEl] = Ref()) -> JsxElement {
    has markerRef: Ref[MarkerEl] = Ref();
    nt: NinetailedCtx = useNinetailed() as NinetailedCtx;
    logger = nt.logger;

    can with entry {
        if markerRef.current {
            markerRef.current.style.setProperty("display", "none", "important");
        }
    }

    can with [logger] entry {
        logger.debug(
            "Using fallback mechanism to detect when experiences are seen. This can lead to inaccurate results. Consider using a forwardRef instead. See: https://docs.ninetailed.io/for-developers/experience-sdk/rendering-experiences#tracking-impressions-of-experiences"
        );
    }

    can with entry {
        if markerRef.current {
            observableElement = getObservableElement(markerRef.current as DomEl);
            ref.current = observableElement;
        }
    }

    <div className="nt-cmp-marker" style={{"display": "none"}} ref={markerRef} />
}
