"""Weather sweep: stations carry Celsius readings, a walker collects them."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[list] = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        self.readings.append([here.name, here.location, here.celsius]);
        print(f"reading {here.celsius}°C at {here.name} ({here.location})");
        visit [-->];
    }
}

with entry {
    root ++> Station(name="North", location="roof", celsius=12.5)
        ++> Station(name="East", location="shed", celsius=18.0)
        ++> Station(name="South", location="garden", celsius=22.3)
        ++> Station(name="West", location="garage", celsius=9.8);

    sweep = WeatherSweep();
    root spawn sweep;

    print("\nFull readings:");
    for (name, loc, temp) in sweep.readings {
        print(f"  {name} ({loc}): {temp}°C");
    }

    temps = [r[2] for r in sweep.readings];
    print(f"\nMin: {min(temps)}°C   Max: {max(temps)}°C");
}
