                />
              ))}
              <a
                className="block px-3 py-2 text-sm text-default-500 hover:text-foreground transition-colors rounded-md hover:bg-default-100"
                href="/guides/"
              >
                Guides
              </a>
            </div>
          </motion.nav>
        )}
      </AnimatePresence>
    </header>
  );
}

