node Hotel {
    has name: str = "";
    has stars: float = 0.0;
}

node Attraction {
    has name: str = "";
    has stars: float = 0.0;
}

edge ConnectsTo {}

walker Planner {
    can start with Root entry {
        print("Tour itinerary (attractions rated 4+ stars):");
        visit [-->];
    }

    can tour with Station entry {
        print(f"\nFrom {here.name}:");
        visit [-->];
    }

    can list with Hotel entry {
        # Hotels are ignored; do not visit further to skip their subtree.
    }

    can rank with Attraction entry {
        if here.stars >= 4.0 {
            print(f"  -> {here.name} ({here.stars} stars)");
        }
        visit [-->];
    }
}

with entry {
    central = Station(name="Central Station");
    north = Station(name="North Station");

    central_hotel = Hotel(name="Grand Plaza", stars=5.0);
    central_attractions = [
        Attraction(name="Old Museum", stars=3.0),
        Attraction(name="Sky Tower", stars=4.5),
        Attraction(name="Riverfront Park", stars=4.0),
    ];

    north_hotel = Hotel(name="Lakeside Inn", stars=4.0);
    north_attractions = [
        Attraction(name="Botanical Garden", stars=5.0),
        Attraction(name="Street Market", stars=3.5),
    ];

    central ++> central_hotel;
    for attr in central_attractions {
        central ++> attr;
    }
    north ++> north_hotel;
    for attr in north_attractions {
        north ++> attr;
    }

    root ++> central ++> north;

    root spawn Planner();
}
