""" Calculate falling factorial of x.
      [https://en.wikipedia.org/wiki/Falling_and_rising_factorials]
  """
def falling_factorial(x: Any, n: Any) -> object {
    c = 1;
    for k in range(n) {
        c *= x - k;
    }
    return c;
}
