"""Tiny dungeon crawler: chained rooms with a single treasure vault.

The hunter walks room by room, counting what it has seen, and bails out
the moment it finds the vault. Rooms past the vault are never visited.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has seen: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can search with Room entry {
        self.seen += 1;
        if here.is_vault {
            self.found = True;
            print(f"[{self.seen}] {here.name} -> TREASURE! Hunter stops.");
            disengage;
        }
        print(f"[{self.seen}] {here.name} ... empty");
        visit [-->] else { disengage; }
    }
}

with entry {
    antechamber = Room(name="Antechamber");
    hall = Room(name="Hall of Echoes");
    crypt = Room(name="Forgotten Crypt");
    vault = Room(name="Dragon Vault", is_vault=True);
    # These rooms exist past the vault but must never be visited.
    beyond = Room(name="Sunken Cellar");
    inner = Room(name="Inner Sanctum");

    root ++> antechamber ++> hall ++> crypt ++> vault ++> beyond ++> inner;

    root spawn Hunter();
}
