"""Order auditor: skip invalid orders but halt entirely on fraud."""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        label = "";
        if here.fraud {
            label = "HALT_FRAUD";
            print(f"[{label}] {here.title} amount={here.amount}");
            disengage;
        } elif not here.valid {
            label = "SKIP";
            print(f"[{label}] {here.title} amount={here.amount}");
            visit [-->];
        } else {
            label = "OK";
            print(f"[{label}] {here.title} amount={here.amount}");
            visit [-->];
        }
    }
}

with entry {
    root ++> Order(title="A", amount=10.0, valid=True, fraud=False)
        ++> Order(title="B", amount=25.0, valid=False, fraud=False)
        ++> Order(title="C", amount=50.0, valid=True, fraud=False)
        ++> Order(title="D", amount=99.0, valid=True, fraud=True)
        ++> Order(title="E", amount=15.0, valid=True, fraud=False);
    root spawn OrderAuditor();
}
