"""Hiking trail: chain waypoints from trailhead to summit and count each stop."""

node Waypoint {
    has label: str = "";
}

walker Hiker {
    has stop_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hike with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->] else {
            print(f"Trail complete — passed {self.stop_count} waypoints.");
            disengage;
        }
    }
}

with entry {
    root ++> Waypoint(label="Trailhead")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint(label="Summit");
    root spawn Hiker();
}
