import from "classnames" { default as classnames }

type TagProps = {
    children: str | None,
    onClose: Callable[[], None] | None,
    closable: bool,
    color: str,
};

glob defaultStyle = "inline-block rounded border border-solid border-slate-200 py-0 px-2 text-xs whitespace-nowrap bg-[#fafafa] h-6 leading-6";

glob colorStyle = "border-transparent text-white";

def:pub Tag(
    children: str | None = None,
    onClose: Callable[[], None] | None = None,
    closable: bool = False,
    color: str = ""
) -> JsxElement {
    has tagRef: Ref[HTMLDivElement] = Ref();

    def handle_close(e: MouseEvent) {
        if onClose {
            onClose();
        }
        if tagRef.current {
            tagRef.current.style.display = "none";
        }
    }

    <div
        className={classnames(defaultStyle, colorStyle if color else "")}
        style={{"backgroundColor": color}}
        ref={tagRef}
    >
        {children}
        {closable and <span className="text-black-50 ml-2 cursor-pointer" onClick={handle_close}>x</span>}
    </div>
}
