def:pub useKeyboardJs(combination: str) -> list[object] {
    statePair = useState([False, None]);
    state = statePair[0];
    setState = statePair[1];
    keyboardJsPair = useState(None);
    keyboardJs = keyboardJsPair[0];
    setKeyboardJs = keyboardJsPair[1];

    useEffect(lambda {
        if not keyboardJs {
            return;
        }
        down = lambda (event: KeyboardEvent) { setState([True, event]); };
        up = lambda (event: KeyboardEvent) { setState([False, event]); };
        getattr(keyboardJs, "bind").call(None, combination, down, up);
        return lambda {
            getattr(keyboardJs, "unbind").call(None, combination, down, up);
        };
    }, [combination, keyboardJs]);

    return state as list[object];
}
