"""Rental shop media shelf audit.

Books and DVDs each have a dedicated entry ability on the Audit walker;
anything else (unclassified archive reels, etc.) falls through to a
default entry ability. The walker counts total items audited and how
many needed the default path.
"""

node Book {
    has title: str = "";
    has author: str = "";
    has available: bool = True;
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
    has available: bool = True;
}

node Reel {
    has title: str = "";
    has medium: str = "";
    has available: bool = True;
}

walker Auditor {
    has total: int = 0;
    has default_count: int = 0;
    has path: list = [];

    can start with Root entry {
        print("Beginning shelf audit...");
        visit [-->] else { disengage; }
    }

    can audit_book with Book entry {
        self.total += 1;
        self.path = self.path + ["book"];
        status = "IN" if here.available else "OUT";
        print(f"  [BOOK/{status}] {here.title} by {here.author}");
        visit [-->] else { disengage; }
    }

    can audit_dvd with DVD entry {
        self.total += 1;
        self.path = self.path + ["dvd"];
        status = "IN" if here.available else "OUT";
        print(f"  [DVD/{status}] {here.title} ({here.runtime} min)");
        visit [-->] else { disengage; }
    }

    # Default handler: fires for any node type that doesn't match Book or DVD.
    can audit_default with Reel entry {
        self.total += 1;
        self.default_count += 1;
        self.path = self.path + ["default"];
        status = "IN" if here.available else "OUT";
        print(f"  [REEL/{status}] unclassified item: {here.title} ({here.medium})");
        visit [-->] else { disengage; }
    }
}

with entry {
    shelf1 = Book(title="The Hobbit", author="Tolkien");
    shelf2 = DVD(title="Blade Runner", runtime=117);
    shelf3 = Reel(title="Newsreel 1942", medium="film");
    shelf4 = Book(title="Dune", author="Herbert", available=False);
    shelf5 = DVD(title="Spirited Away", runtime=125, available=False);
    shelf6 = Reel(title="Promo Reel", medium="magnetic");

    root ++> shelf1
        ++> shelf2
        ++> shelf3
        ++> shelf4
        ++> shelf5
        ++> shelf6;

    auditor = Auditor();
    root spawn auditor;

    print("");
    print(f"Audit complete: {auditor.total} items audited, {auditor.default_count} took the default path");
    print(f"Path taken: {auditor.path}");
}
