const DragPanel: React.FC<IDragComponent> = () => {
  const { lineColor, backgroundColor, registerNodes, setDragType } =
    useContext(BuilderContext);

  const handleDragStart = (type: string) => {
    setDragType(type);
  };

  const handleDragEnd = () => {
    setDragType('');
  };

  return (
