"""Convert a sequence of IOB tags to BIO tags."""
def convert_iob_to_bio(seq: list[str]) -> list[str] {
    new: list[str] = [];
    prev = 'O';
    for token in seq {
        current = token;
        if current.startswith('I-') {
            if prev == 'O' or current[2:] != prev[2:] {
                current = 'B-' + current[2:];
            }
        }
        new.append(current);
        prev = current;
    }
    return new;
}
