        visit [-->];
    }
}

walker AnnounceRobot {
    has robot_label: str = "";
    has stops: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can log with Station entry {
        self.stops += 1;
        announcement = f"Robot {self.robot_label} stopped at {here.name}";
        print(announcement);
        visit [-->];
    }
}

