"""Warehouse stock take: walk the shelves, report per-item counts and totals."""

node Item {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    has total_units: int = 0;
    has smallest_qty: int = 0;
    has initialized: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can tally with Item entry {
        report here;
        self.total_units = self.total_units + here.quantity;
        if not self.initialized {
            self.smallest_qty = here.quantity;
            self.initialized = True;
        } else {
            if here.quantity < self.smallest_qty {
                self.smallest_qty = here.quantity;
            }
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Item(sku="A-001", quantity=42)
        ++> Item(sku="B-204", quantity=15)
        ++> Item(sku="C-777", quantity=88)
        ++> Item(sku="D-050", quantity=3);

    counter = Counter();
    result = root spawn counter;

    print("Per-item counts:");
    for r in result.reports {
        item = r;
        print(f"  {item.sku}: {item.quantity}");
    }
    print(f"Total units in warehouse: {counter.total_units}");
    print(f"Smallest shelf count: {counter.smallest_qty}");
}
