import from ffmpeg.util { fetchFile }
import from pages.tools.video.trim.types { InitialValuesType }
import re;

async def trimVideo(input: bytes, input_filename: str, options: InitialValuesType) -> tuple[bytes, str] {
    async def task(ctx: dict) -> tuple[bytes, str] {
        ffmpeg = ctx["ffmpeg"];
        tempFile = ctx["tempFile"];
        inputName = tempFile(".mp4");
        outputName = tempFile(".mp4");
        await ffmpeg.writeFile(inputName, await fetchFile(input));
        await ffmpeg.exec([
            "-i",
            inputName,
            "-ss",
            str(options.start),
            "-to",
            str(options.end),
            "-c",
            "copy",
            outputName
        ]);
        trimmedData = await ffmpeg.readFile(outputName);
        baseName = re.sub(r"\.[^/.]+$", "", input_filename);
        outputFilename = f"{baseName}_trimmed.mp4";
        return (trimmedData, outputFilename);
    }
    return await runFFmpegTask(task);
}
