"""Build dependency audit: diamond-safe total of build minutes.

The graph can have diamonds — a task reachable by several paths. A plain
`visit [-->]` re-enters shared tasks; we must count each task's minutes
exactly once. We track visited nodes via an explicit guard set on the
walker (Jac 0.36.1 has no built-in once-per-node visitation, see probe
notes) and only visit an unvisited node's outgoing dependencies.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

walker Auditor {
    has total_minutes: int = 0;
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if here.title not in self.visited {
            self.visited.append(here.title);
            self.total_minutes += here.minutes;
            print(f"  audited {here.title} (+{here.minutes} min)");
        } else {
            print(f"  skip {here.title} (already audited)");
        }
        visit [-->];
    }
}

walker BuildRunner {
    can run_build with Root entry {
        visit [-->];
    }

    can run_task with Task entry {
        status = "START" if here.minutes > 0 else "END";
        print(f"[{status}] {here.title}");
        visit [-->];
    }
}

with entry {
    # Diamond shape:
    #   core and util are shared; parser and linker both depend on them.
    core = Task(title="core", minutes=5);
    util = Task(title="util", minutes=3);
    parser = Task(title="parser", minutes=7);
    linker = Task(title="linker", minutes=4);

    root ++> core ++> util;
    root ++> parser;
    root ++> linker;
    parser ++> core;
    parser ++> util;
    linker ++> core;
    linker ++> util;

    print("Build traversal order:");
    root spawn BuildRunner();

    print("\nAuditing (each task counted once even with diamond paths):");
    auditor = Auditor();
    root spawn auditor;
    print(f"\nTOTAL build minutes = {auditor.total_minutes}");
}
