"""Tiny dungeon crawler: chained rooms with a treasure vault.

A Hunter walker walks the rooms one by one, counts the rooms it has
visited, and disengages the moment it enters the treasure room so that
no room past the vault is ever visited.
"""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        print(f"Entering {here.name} (rooms checked: {self.rooms_checked})");
        if here.has_treasure {
            print(f"Treasure found in {here.name}! Hunter disengages.");
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Room(name="Antechamber")
        ++> Room(name="Hall of Whispers")
        ++> Room(name="Armory")
        ++> Room(name="Treasure Vault", has_treasure=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Dragon's Lair");

    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter visited {hunter.rooms_checked} rooms total.");
}
