    fetchArticles();
  }, [fetchArticles]);

  useEffect(() => {
    if (!refreshRate) return;

    const interval = setInterval(() => {
      fetchArticles();
    }, refreshRate * 60 * 1000);

    return () => clearInterval(interval);
  }, [refreshRate, fetchArticles]);

  return (
    <BaseWidget
      title="Dev.to Articles"
      icon="📝"
      loading={loading}
      error={error}
      onRefresh={fetchArticles}
