def:pub recommendNextMove(score: int, canNext: bool, hasSample: bool) -> dict[str, str] {
    if ((score <= 7) and hasSample) {
        return {"action": "sample", "label": "Study the sample answer", "reason": ("Low score — study a strong sample, then revise your answer below." if (score <= 5) else "Almost there — compare with a strong sample to sharpen it.")};
    }
    if (score >= 8) {
        return {"action": "real_interview", "label": "Practice in real interview", "reason": "Strong answer — rehearse it in the real interview setting."};
    }
    if canNext {
        return {"action": "next", "label": "Next question", "reason": ("Apply the feedback below, then keep your momentum going." if (score <= 7) else "Strong answer — keep your momentum going.")};
    }
    return {"action": "finish", "label": "Finish & view report", "reason": "Last question done — wrap up and review your session report."};
}

