node Waypoint {
    has stop: int = 0;
}

walker Hiker {
    has target_stops: int = 4;
    has visited: int = 0;

    can start with Root entry {
        print("Starting the hike from the trailhead.");
        visit [-->] else { disengage; }
    }

    can hike with Waypoint entry {
        self.visited += 1;
        print(f"Stop #{here.stop}");
        if self.visited >= self.target_stops {
            print("Completed enough of the trail. Summit bound!");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Waypoint(stop=1)
        ++> Waypoint(stop=2)
        ++> Waypoint(stop=3)
        ++> Waypoint(stop=4)
        ++> Waypoint(stop=5)
        ++> Waypoint(stop=6);
    root spawn Hiker(target_stops=4);
}
