import from "@jac/runtime" { useParams }
import from "next/link" { default as Link }
import from "../../utils/api.jac" { fetchUserById, fetchItemById }
import from "../../utils/time.jac" { relativeTime }

glob PAGE_SIZE = 15;

def format_joined_date(timestamp: int) -> str {
    d = new(Date, timestamp * 1000);
    return d.toLocaleDateString() as str;
}

def:pub UserProfilePage() -> JsxPage {
    params = useParams();
    username = params["username"] as str;

    has user: dict[str, object] | None = None;
    has loading: bool = True;
    has error: bool = False;
    has submissions: list[dict[str, object]] = [];
    has loaded_count: int = 0;
    has loading_more: bool = False;

    async def load_more(ids: list[int], from_idx: int) {
        loading_more = True;
        slice_ids = ids[from_idx:from_idx + PAGE_SIZE];
        items: list[dict[str, object]] = [];
        for item_id in slice_ids {
            item = await fetchItemById(item_id) as dict[str, object];
            items.append(item);
        }
        valid = [it for it in items if it and not it.get("deleted") and not it.get("dead")];
        submissions = submissions + valid;
        loaded_count = from_idx + len(slice_ids);
        loading_more = False;
    }

    async def handle_load_more() {
        if user and user.get("submitted") {
            submitted_ids = user["submitted"] as list[int];
            await load_more(submitted_ids, loaded_count);
        }
    }

    async can with [username] entry {
        try {
            user_data = await fetchUserById(username);
            if not user_data {
                error = True;
            } else {
                user = user_data as dict[str, object];
            }
        } except Exception as err {
            console.error("Failed to fetch user:", err);
            error = True;
        } finally {
            loading = False;
        }
    }

    async can with [user] entry {
        if user and user.get("submitted") {
            submitted_ids = user["submitted"] as list[int];
            if len(submitted_ids) > 0 {
                await load_more(submitted_ids, 0);
            }
        }
    }

    if loading {
        return (
            <div className="flex justify-center items-center my-4 h-32">
                <p className="text-lg text-neutral-400">Loading...</p>
            </div>
        );
    }

    if error or not user {
        return (
            <div className="container mx-auto p-6">
                <h1 className="text-xl text-orange-400 mb-2">User not found</h1>
                <p className="text-neutral-400">
                    No Hacker News user with id <span className="text-neutral-200">{username}</span> exists.
                </p>
            </div>
        );
    }

    user_submitted = user["submitted"] as list[int] if user.get("submitted") else [];
    total_submissions = len(user_submitted);
    has_more = loaded_count < total_submissions;
    user_id = user["id"] as str;
    user_created = user.get("created");
    user_karma = user.get("karma");
    user_about = user.get("about") as str | None;
    karma_display = user_karma if isinstance(user_karma, int) or isinstance(user_karma, float) else "N/A";

