            </h2>

            <p className='mt-1 text-xs font-semibold'>
              Level: {candidate.minimumLevel} - {inspectedLevelCap.level} (
              {inspectedLevelCap.description})
            </p>
            <p className='mt-1 text-xs font-semibold'>
              IV Floor: {floor.value}{' '}
              {floor.name !== null ? `(${floor.name})` : ''}
            </p>
            <p className='mt-1 text-xs font-semibold'>
              Ranked By: {rankingMetric.name}
