"""Wildlife park feeding rounds.

The kiosk greets every tour party regardless of who they are; zookeepers
feed each animal its species-appropriate meal; school groups just watch
the animals pass by.
"""

node Animal {
    has name: str = "";
    has species: str = "";

    def feed_plan() -> str {
        return "standard feed";
    }
}

node Lion(Animal) {
    override def feed_plan() -> str {
        return "meat";
    }
}

node Parrot(Animal) {
    override def feed_plan() -> str {
        return "seed";
    }
}

node Enclosure { has label: str = ""; }

edge Holds { has label: str = ""; }

walker TourParty {
    has party_name: str = "";

    can start with Root entry {
        print(f"Welcome to the park, {self.party_name}!");
        visit [-->];
    }

    can arrive with Enclosure entry {
        print(f"{self.party_name} viewing enclosure: {here.label}");
        visit [-->];
    }

    can watch with Lion | Parrot | Animal entry {
        print(f"{self.party_name} watches {here.name} the {here.species}");
    }
}

walker Zookeeper {
    has keeper_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can service with Enclosure entry {
        print(f"Zookeeper {self.keeper_name} servicing {here.label}");
        visit [-->];
    }

    can feed with Lion | Parrot | Animal entry {
        meal = here.feed_plan();
        print(f"Feeding {here.name} the {here.species}: {meal}");
    }
}

walker SchoolGroup {
    has class_name: str = "";

    can start with Root entry {
        print(f"School group {self.class_name} has arrived for a lesson");
        visit [-->];
    }

    can observe with Enclosure entry {
        print(f"{self.class_name} observes enclosure: {here.label}");
        visit [-->];
    }

    can learn with Lion | Parrot | Animal entry {
        print(f"{self.class_name} takes notes on {here.name} the {here.species}");
    }
}

with entry {
    savanna = Enclosure(label="Savanna");
    aviary = Enclosure(label="Aviary");
    pond = Enclosure(label="Pond");

    simba = Lion(name="Simba", species="Lion");
    polly = Parrot(name="Polly", species="Parrot");
    ducky = Animal(name="Ducky", species="Duck");

    root +>:Holds:+> savanna +>:Holds:+> simba;
    root +>:Holds:+> aviary +>:Holds:+> polly;
    root +>:Holds:+> pond +>:Holds:+> ducky;

    print("--- Tour party ---");
    root spawn TourParty(party_name="The Hendersons");

    print("--- Zookeeper rounds ---");
    root spawn Zookeeper(keeper_name="Alex");

    print("--- School group ---");
    root spawn SchoolGroup(class_name="Room 12B");
}
