"""Restaurant kitchen line health-inspection walker.

A single ``KitchenInspector`` walker visits every station (Grill, Fryer,
ColdPrep) and runs two checks at each one: a temperature guard (above 40 C
is a violation) and a visit log. Both checks fire at every station, so we
use a union ability on a shared base to keep the routine typed.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
}

node Grill(Station) {
    has temperature: float = 200.0;
}

node Fryer(Station) {
    has temperature: float = 175.0;
}

node ColdPrep(Station) {
    has temperature: float = 4.0;
}

walker KitchenInspector {
    has violations: int = 0;
    has stations_checked: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("Health inspector beginning kitchen line walk-through");
        visit [-->];
    }

    can inspect with Grill | Fryer | ColdPrep entry {
        self.stations_checked += 1;
        entry = f"Visited station {here.name} ({here.temperature} C)";
        self.log.append(entry);
        print(entry);
        if here.temperature > 40.0 {
            self.violations += 1;
            violation = f"VIOLATION at {here.name}: {here.temperature} C exceeds 40 C";
            self.log.append(violation);
            print(violation);
        }
        visit [-->];
    }
}

with entry {
    root ++> Grill(name="Char Grill")
        ++> Fryer(name="Deep Fryer")
        ++> ColdPrep(name="Salad Station");

    inspector = KitchenInspector();
    root spawn inspector;

    print(
        f"Inspection summary: {inspector.stations_checked} stations checked, "
        f"{inspector.violations} violation(s)"
    );
}
