"""Tiny dungeon crawler: chain of room nodes with one treasure vault.

A Hunter walker counts rooms it enters and stops the whole search the
moment it reaches the vault, so rooms past the vault are never visited.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        if here.is_vault {
            print(f"Found the treasure in {here.name}! "
                  f"Searched {self.rooms_checked} room(s).");
            disengage;
        } else {
            print(f"Checked {here.name}... empty.");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Armory")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Hidden Chamber")
        ++> Room(name="Throne Room");

    hunter = Hunter();
    root spawn hunter;

    print(f"Total rooms checked before stopping: {hunter.rooms_checked}");
}
