node Waypoint {
    has stop_number: int = 0;
}

walker Hiker {
    has goal: int = 0;
    has passed: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hike with Waypoint entry {
        self.passed += 1;
        print(f"stop #{here.stop_number}: {self.passed} waypoint(s) passed");
        if self.passed >= self.goal {
            print(f"Trial complete: passed {self.passed} waypoints (goal was {self.goal})");
            disengage;
        }
        visit [-->];
    }
}

