    StatRow(iconKey="location", label="Location", value="New York, US"),
];

def stat_icon(iconKey: str) -> JsxElement {
    if iconKey == "message" {
        return <MessageSquareIcon className="size-3.5 text-muted-foreground" />;
    } elif iconKey == "clock" {
        return <ClockIcon className="size-3.5 text-muted-foreground" />;
    }
    return <MapPinIcon className="size-3.5 text-muted-foreground" />;
}

def initials_from_name(name: str) -> str {
    parts = name.split(" ");
    return "".join([part[0] for part in parts]).upper();
}

