                        <motion.span
                            animate={{"rotate": 90 if open else 0}}
                            transition={{"duration": 0.25, "ease": "easeInOut"}}
                            className="inline-flex"
                        >
                            <ChevronRightIcon aria-hidden="true" className="text-muted-foreground size-4" />
                        </motion.span>
                    </div>
                </CollapsibleTrigger>
