                            }}
                            <a
                                href={profileHref}
                                className="flex items-center gap-1.5 px-4 py-3 text-sm font-medium text-primary hover:underline"
                            >
                                View profile
                                <ArrowRight className="size-3.5" />
                            </a>
                        </motion.div>
                    }}
                </AnimatePresence>
            </Collapsible>
        </div>
    </div>
}
