import from "react" { useEffect, useState }

glob DAY_MS: int = 24 * 60 * 60 * 1000;

obj DailyLimit {
    has limited: bool,
        limit: int,
        used: int,
        resetAt: int;
}

def useDailyLimit() -> DailyLimit | None {
    day_state = useState(0);
    todayKey = day_state[0] as int;
    setTodayKey = day_state[1];
    useEffect(lambda {
        now = Date.now() as int;
        setTodayKey(int(now / DAY_MS));
        untilRollover = ((todayKey + 1) * DAY_MS - now) as int;
        timer = window.setTimeout(
            lambda {
                setTodayKey(int((Date.now() as int) / DAY_MS));
            },
            float(max(1000, untilRollover)),
        );
        return lambda { window.clearTimeout(timer); };
    }, [todayKey]);
    return None;
}

def resetLabel(resetAt: int) -> str {
    now = Date.now() as int;
    hours = int((resetAt - now + 3599999) / 3600000);
    if hours <= 1 {
        return "in less than an hour";
    }
    return f"in about {hours} hours";
}
