"""Tiny blogging service: private drafts on the author's root, public articles
on the shared graph, cascade delete of comments when an article is removed,
and walkers for the public feed, article view, comments, drafts, and cleanup."""

# ---------- Node archetypes ----------

node Draft {
    has title: str = "";
    has body: str = "";
}

node Article {
    has title: str = "";
    has body: str = "";
}

node Comment {
    has author: str = "";
    has body: str = "";
}

# ---------- Public walkers (shared graph) ----------

walker PublicFeed {
    has feed: list = [];

    can start with Root entry {
        self.feed = [];
        visit [-->];
    }

    can collect with Article entry {
        self.feed.append({
            "title": here.title,
            "preview": here.body[:40],
        });
        visit [-->];
    }
}

walker ArticleView {
    has title_query: str = "";
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can read with Article entry {
        if here.title == self.title_query {
            self.found = True;
            print(f"=== {here.title} ===");
            print(here.body);
            print(f"--- {len([-->])} comment(s) ---");
            visit [-->];
        } else {
            visit [-->];
        }
    }
}

walker CommentPoster {
    has title_query: str = "";
    has author_name: str = "";
    has comment_body: str = "";
    has success: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can find_article with Article entry {
        if here.title == self.title_query {
            self.success = True;
            here ++> Comment(author=self.author_name, body=self.comment_body);
            print(f"Comment by {self.author_name} added to '{here.title}'");
            disengage;
        } else {
            visit [-->];
        }
    }
}

walker ArticleDeleter {
    has title_query: str = "";
    has removed: bool = False;
    has comment_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can find_target with Article entry {
        if here.title == self.title_query {
            for c in [-->] {
                self.comment_count += 1;
                del c;
            }
            article_ref = here;
            del article_ref;
            self.removed = True;
            print(f"Deleted '{self.title_query}' "
                  f"({self.comment_count} comment(s) cascaded)");
            disengage;
        } else {
            visit [-->];
        }
    }
}

# ---------- Private walkers (author's own root) ----------

walker DraftManager {
    has action: str = "list";
    has title_query: str = "";
    has new_body: str = "";
    has result: list = [];
    has draft: object = None;

    can start with Root entry {
        if self.action == "create" {
            d = Draft(title=self.title_query, body=self.new_body);
            root ++> d;
            self.draft = d;
            print(f"Draft '{self.title_query}' saved privately");
        } else {
            visit [-->];
        }
    }

    can manage with Draft entry {
        if self.action == "list" {
            self.result.append({
                "title": here.title,
                "body_preview": here.body[:30],
            });
            visit [-->];
        } elif self.action == "edit" and here.title == self.title_query {
            here.body = self.new_body;
            self.draft = here;
            print(f"Draft '{here.title}' updated");
            visit [-->];
        } elif self.action == "delete" and here.title == self.title_query {
            self.draft = here;
            del here;
            print(f"Draft '{self.title_query}' deleted");
            visit [-->];
        } else {
            visit [-->];
        }
    }
}

walker PublishDraft {
    has title_query: str = "";
    has published: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can publish with Draft entry {
        if here.title == self.title_query {
            published_body = here.body;
            article = Article(title=here.title, body=published_body);
            root ++> article;
            to_delete = here;
            del to_delete;
            self.published = True;
            print(f"Published '{self.title_query}' to the public graph");
            disengage;
        } else {
            visit [-->];
        }
    }
}

# ---------- Demo wiring ----------

with entry {
    root spawn DraftManager(action="create", title_query="Spa Day",   new_body="notes from the spa...");
    root spawn DraftManager(action="create", title_query="Ramen Run", new_body="try the new place on 5th");
    root spawn DraftManager(action="create", title_query="Old Idea",  new_body="never published");

    root spawn PublishDraft(title_query="Spa Day");
    root spawn PublishDraft(title_query="Ramen Run");

    feed_walker = PublicFeed();
    root spawn feed_walker;
    print(f"Public feed has {len(feed_walker.feed)} article(s): "
          f"{[a['title'] for a in feed_walker.feed]}");

    root spawn ArticleView(title_query="Ramen Run");

    root spawn CommentPoster(title_query="Ramen Run",
                              author_name="alice", comment_body="love this place!");
    root spawn CommentPoster(title_query="Ramen Run",
                              author_name="bob",   comment_body="how spicy?");

    root spawn ArticleView(title_query="Ramen Run");

    deleter = ArticleDeleter(title_query="Ramen Run");
    root spawn deleter;
    print(f"Cascade result: removed={deleter.removed}, "
          f"comments_purged={deleter.comment_count}");

    feed2 = PublicFeed();
    root spawn feed2;
    print(f"Public feed after delete has {len(feed2.feed)} article(s): "
          f"{[a['title'] for a in feed2.feed]}");

    drafts = DraftManager(action="list");
    root spawn drafts;
    print(f"Private drafts remaining: "
          f"{[d['title'] for d in drafts.result]}");
}
