import os;

def:pub errorHandler(err: ErrorInfo, _req: object, res: Response, _next: object) -> object {
    return res.status(404).json({
        "status": "error",
        "message": err.message,
        "stack": (
            (os.environ.get("NODE_ENV") == "development")
            and [
                line.replace("/".join(os.getcwd().split(path.sep)), ".")
                for line in [
                    "/".join(line.split(path.sep))
                    for line in [line.strip() for line in (err.stack or "").split("\n")]
                ]
            ]
        ),
    });
}
