import from "react" { useEffect }

obj UseEscapeKeyOptions {
    has enabled: bool;
    has onEscape: Callable[[], None];
    has priority: int = 0;
}

def:pub useEscapeKey(options: UseEscapeKeyOptions) {
    enabled = options.enabled;
    onEscape = options.onEscape;
    priority = options.priority;
    useEffect(lambda {
        if not enabled {
            return lambda { };
        }
        def handleEscape(e: KeyboardEvent) {
            if e.key != "Escape" {
                return;
            }
            if e.defaultPrevented {
                return;
            }
            eventData = e as dict[str, object];
            currentPriority = eventData.get("_escPriority", -1) as int;
            if priority > currentPriority {
                eventData["_escPriority"] = priority;
                e.stopPropagation();
                e.preventDefault();
                onEscape();
            }
        }
        document.addEventListener("keydown", handleEscape, {"capture": True});
        return lambda { document.removeEventListener("keydown", handleEscape, {"capture": True}); };
    }, [enabled, onEscape, priority]);
}
