import from "motion/react" { motion, AnimatePresence }
import from "lucide-react" { AlertTriangle, Check, ShieldAlert }
import from "@/lib/utils" { cn }

def:pub HoldToChargeButton(
    label: str = "Hold to Delete",
    holdingLabel: str = "Holding...",
    completedLabel: str = "Deleted Successfully!",
    holdDuration: int = 1500,
    autoResetDelay: int = 3000,
    onComplete: Callable[[], None] | None = None,
    variant: str = "destructive",
    className: str = "",
    onMouseDown: Callable[[MouseEvent], None] | None = None,
    onMouseUp: Callable[[MouseEvent], None] | None = None,
    onMouseLeave: Callable[[MouseEvent], None] | None = None,
    onTouchStart: Callable[[TouchEvent], None] | None = None,
    onTouchEnd: Callable[[TouchEvent], None] | None = None,
    props: dict[str, object] = {},
    ref: Ref[HTMLButtonElement] = Ref(),
) -> JsxElement {
    has progress: float = 0.0;
    has isHolding: bool = False;
    has isCompleted: bool = False;
    has animationFrameRef: Ref[int | None] = Ref();
    has startTimeRef: Ref[float | None] = Ref();
    isDestructive = variant == "destructive";

    def stop_holding() {
        isHolding = False;
        if animationFrameRef.current {
            cancelAnimationFrame(animationFrameRef.current);
            animationFrameRef.current = None;
        }
        startTimeRef.current = None;
        if not isCompleted {
            progress = 0.0;
        }
    }

    def update_progress(_now: float) -> None {
        if not startTimeRef.current { return; }
        elapsed = float(Date.now()) - startTimeRef.current;
        currentProgress = min((elapsed / holdDuration) * 100, 100);
        progress = currentProgress;
        if currentProgress >= 100 {
            isCompleted = True;
            isHolding = False;
            if onComplete { onComplete(); }
            if autoResetDelay > 0 {
                setTimeout(lambda {
                    isCompleted = False;
                    progress = 0.0;
                }, autoResetDelay);
            }
        } else {
            animationFrameRef.current = requestAnimationFrame(update_progress);
        }
    }

    def start_holding() {
        if isCompleted { return; }
        isHolding = True;
        startTimeRef.current = float(Date.now());
        animationFrameRef.current = requestAnimationFrame(update_progress);
    }

    can with exit {
        if animationFrameRef.current {
            cancelAnimationFrame(animationFrameRef.current);
        }
    }

    def handle_mouse_down(e: MouseEvent) {
        start_holding();
        if onMouseDown { onMouseDown(e); }
    }

    def handle_mouse_up(e: MouseEvent) {
        stop_holding();
        if onMouseUp { onMouseUp(e); }
    }

    def handle_mouse_leave(e: MouseEvent) {
        stop_holding();
        if onMouseLeave { onMouseLeave(e); }
    }

    def handle_touch_start(e: TouchEvent) {
        start_holding();
        if onTouchStart { onTouchStart(e); }
    }

    def handle_touch_end(e: TouchEvent) {
        stop_holding();
        if onTouchEnd { onTouchEnd(e); }
    }

    <motion.button
        ref={ref}
        onMouseDown={handle_mouse_down}
        onMouseUp={handle_mouse_up}
        onMouseLeave={handle_mouse_leave}
        onTouchStart={handle_touch_start}
        onTouchEnd={handle_touch_end}
        whileHover={{"scale": 1.0 if isCompleted else 1.02}}
        whileTap={{"scale": 1.0 if isCompleted else 0.97}}
        className={cn(
            "group relative inline-flex items-center justify-center gap-2 overflow-hidden rounded-xl px-6 py-3 font-medium text-sm transition-all duration-300 select-none outline-none min-w-44 border",
            "border-green-500 bg-green-500/10 text-green-600" if isCompleted and isDestructive else "border-destructive/50 bg-destructive/10 text-destructive hover:bg-destructive/20" if isDestructive else "border-border bg-background text-foreground hover:bg-muted",
            "cursor-grabbing" if isHolding else "cursor-pointer" if not isCompleted else "cursor-not-allowed!",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
            className,
        )}
        {**props}
    >
        <motion.span
            className={cn("absolute inset-y-0 left-0 origin-left", "bg-destructive/20" if isDestructive else "bg-primary/20")}
            style={{"width": f"{progress}%"}}
