"""Dungeon crawler: chained room nodes with a treasure room guarded by a hunter walker.

The hunter walks the chain room by room, counting visits, and disengages the
moment it steps into the treasure vault. Anything past the vault is never
visited.
"""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has visited_count: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else {
            print("No rooms to explore.");
            disengage;
        }
    }

    can explore with Room entry {
        self.visited_count += 1;
        print(f"  [{self.visited_count}] Entering '{here.name}'");
        if here.is_treasure {
            print(f"Treasure found in '{here.name}'! Hunter stops.");
            disengage;
        }
        visit [-->] else {
            print("Hallway ends. Hunter returns empty-handed.");
            disengage;
        }
    }
}

