node Hotel {
    has name: str = "";
    has rooms: int = 0;
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

walker ItineraryPlanner {
    has min_stars: int = 4;

    can start with Root entry {
        visit [-->];
    }

    can plan with Station entry {
        print(f"Itinerary from station: {here.name}");
        visit [-->];
    }

    can filter with Hotel | Attraction entry {
        # Only attractions make the cut; hotels are skipped silently.
        visit [-->];
    }

    can shortlist with Attraction entry {
        if here.stars >= self.min_stars {
            rating = f"{here.stars}-star";
            print(f"  -> {rating} attraction: {here.name}");
        }
        visit [-->];
    }
}

