import { NextRequest, NextResponse } from "next/server";

const CHINA_COUNTRY_CODES = new Set(["CN", "HK", "MO", "TW"]);

export function GET(request: NextRequest) {
  const country =
    request.headers.get("x-vercel-ip-country") ??
    request.headers.get("cf-ipcountry") ??
    request.headers.get("x-country-code") ??
    null;

  const suggestedLocale =
    country && CHINA_COUNTRY_CODES.has(country.toUpperCase()) ? "zh" : "en";

  return NextResponse.json({ locale: suggestedLocale, country });
}

```jac
glob CHINA_COUNTRY_CODES: set[str] = {"CN", "HK", "MO", "TW"};

def:pub GET(headers: dict[str, str] | None = None) -> dict[str, str | None] {
    hdrs = headers if headers is not None else {};
    country = (
        hdrs.get("x-vercel-ip-country")
        or hdrs.get("cf-ipcountry")
        or hdrs.get("x-country-code")
    );
    suggestedLocale = "zh" if (country and country.upper() in CHINA_COUNTRY_CODES) else "en";
    return {"locale": suggestedLocale, "country": country};
}
